/* Original scaffolded problems: each answer feeds the next solving decision. */
(function(root){
 const M=root.StudyMath||(typeof require!=='undefined'?require('./math.js'):null),n=(label,value,tolerance=.01)=>({label,value,tolerance}),step=(title,why,question,fields,solution)=>({title,why,question,fields,solution}),choice=(title,why,question,options,answer,solution)=>({title,why,question,options,answer,solution});
 const A=[1,1,0],B=[4,5,0],d=M.directedForce(A,B,100),proj=M.projection([100,50,0],d.displacement),mom=M.moment([0,0,0],[2,1,0],[50,100,0]),ax=M.forceAxisMoment([0,0,0],[3,4,0],[2,1,0],[0,0,100]),couple=M.couple([2,3,0],[0,0,0],[0,100,0]),r=M.resultant(120,30,90,120);
 const coordinates=()=>step('Read the coordinates','Before subtracting points, identify the common origin, axis directions and units. A coordinate locates a point; it is not the displacement between two points.','Read A and B from the labelled xy diagram. Both points lie in z = 0.',[...A.map((v,i)=>n('A'+['x','y','z'][i]+' (m)',v)),...B.map((v,i)=>n('B'+['x','y','z'][i]+' (m)',v))],'A = (1, 1, 0) m and B = (4, 5, 0) m. Coordinates are measured from O along the positive axes.');
 const displacement=()=>step('Build the direction vector','For A→B, subtract ending point minus starting point. The order fixes the positive axis direction.','Find rAB = B − A.',d.displacement.map((v,i)=>n('r'+['x','y','z'][i]+' (m)',v)),'rAB = (4 − 1, 5 − 1, 0 − 0) = (3, 4, 0) m.');
 const unit=()=>step('Normalize the direction','Divide the displacement by its full point-to-point length to preserve its direction while making its magnitude one. The resulting unit vector is dimensionless.','Find |rAB| and uAB.',[n('Length (m)',5),...d.unit.map((v,i)=>n('u'+['x','y','z'][i]+' (unitless)',v,.005))],'|rAB| = √(3² + 4² + 0²) = 5 m. uAB = rAB/5 = (0.6, 0.8, 0); |uAB| = 1.');
 const problems=[
 {id:'resultants',title:'Force resultants',workspace:'lesson',description:'Resolve directions, add signed components, then recover magnitude and angle.',prompt:'Two forces act at O: <strong>A = 120 N at 30°</strong> and <strong>B = 90 N at 120°</strong>, counterclockwise from +x. Find their resultant.',diagram:'resultants',steps:[choice('Choose a component method','Both magnitudes and angles from +x are given. Perpendicular Cartesian components make vector addition straightforward.','Which components are correct for a force angle measured from +x?',['Fx = F cos θ, Fy = F sin θ','Fx = F sin θ, Fy = F cos θ','Fx = Fy = F'],0,'Cosine gives the adjacent x component; sine gives the y component. Signs follow the angle’s quadrant.'),step('Resolve both forces','Each force has its own direction angle. B lies in quadrant II, so its x component must be negative.','Calculate the four signed components.',[n('Ax (N)',r.ax,.1),n('Ay (N)',r.ay,.1),n('Bx (N)',r.bx,.1),n('By (N)',r.by,.1)],'Ax = 120 cos 30° = 103.923 N; Ay = 60 N. Bx = 90 cos 120° = −45 N; By = 77.942 N.'),step('Add matching components','Vector addition combines signed components along the same axis. Do not add the force magnitudes.','Find Rx and Ry.',[n('Rx (N)',r.x,.1),n('Ry (N)',r.y,.1)],'Rx = 103.923 − 45 = 58.923 N; Ry = 60 + 77.942 = 137.942 N.'),step('Recover the magnitude','x and y are perpendicular, so the Pythagorean theorem gives the resultant magnitude.','Find R.',[n('R (N)',r.magnitude,.1)],'R = √(Rx² + Ry²) = 150 N.'),step('Find and check the direction','Use both signed components to determine the quadrant. Here Rx and Ry are positive, so the angle belongs in quadrant I.','Find θ counterclockwise from +x (degrees).',[n('θ (degrees)',r.angle,.2)],'θ = atan2(Ry, Rx) = 66.870°; the resultant lies between the original force directions.')]},
 {id:'position',title:'Position & unit vectors',workspace:'position',description:'Read points, build displacement, normalize, then construct a cable force.',prompt:'A cable pulls at <strong>A</strong> toward <strong>B</strong> with magnitude <strong>100 N</strong>. Read the endpoints from the diagram and find the Cartesian force.',diagram:'coordinates',steps:[coordinates(),displacement(),unit(),step('Construct the cable force','The cable pulls at A toward B. Multiplying a dimensionless direction by the force magnitude supplies the newton units.','Find F = 100 uAB.',d.force.map((v,i)=>n('F'+['x','y','z'][i]+' (N)',v,.1)),'F = 100(0.6, 0.8, 0) = (60, 80, 0) N.'),step('Check the result','The force-vector magnitude should equal the given cable force. This catches a direction vector that was not normalized.','Find |F|.',[n('|F| (N)',100,.1)],'√(60² + 80² + 0²) = 100 N. Unit components have no units; force components have N.')]},
 {id:'projection',title:'Force projections',workspace:'projection',description:'Locate the axis endpoints, normalize its direction, then project the force.',prompt:'Force <strong>F = (100, 50, 0) N</strong> acts at O. The positive projection axis points <strong>A→B</strong>. Find the signed scalar projection and the parallel force vector.',diagram:'coordinates',steps:[coordinates(),displacement(),unit(),step('Take the scalar projection','The dot product with the positive axis unit vector gives the signed force component along that axis. Coordinates define the axis; they are not force components.','Find Faxis = F · uAB.',[n('Signed projection (N)',proj.scalar,.1)],'Faxis = 100(0.6) + 50(0.8) + 0(0) = 100 N. Positive means along A→B.'),step('Recover the parallel vector','The scalar projection is one number. Multiply it by the unit axis direction to obtain the vector in Cartesian form.','Find Fparallel = Faxis uAB.',proj.parallel.map((v,i)=>n('Fparallel '+['x','y','z'][i]+' (N)',v,.1)),'Fparallel = 100(0.6, 0.8, 0) = (60, 80, 0) N.'),choice('Check the axis convention','Reversing A→B negates both u and the scalar projection. Their product stays the same.','If the positive axis is reversed, what changes?',['Scalar becomes −100 N; parallel vector stays (60, 80, 0) N','Scalar stays +100 N; vector reverses','Both scalar and parallel vector reverse'],0,'(F · (−u))(−u) = (F · u)u. The signed scalar depends on the chosen positive direction; the parallel vector does not.')]},
 {id:'moments',title:'Moments & cross products',workspace:'moment',description:'Choose the reference, build the moment arm, cross with force and check rotation.',prompt:'Force <strong>F = (50, 100, 0) N</strong> acts at <strong>P = (2, 1, 0) m</strong>. Find its moment about <strong>O = (0, 0, 0) m</strong>.',steps:[choice('Choose the moment reference','The position vector used in a moment starts at the point about which the moment is requested.','Where must r begin?',['At O, ending at P on the force line','At the force arrow tip','At any unrelated point'],0,'Use rOP. The reference changes the moment of a single force.'),step('Build the position vector','Subtract application point minus reference point using the same coordinate system.','Find rOP = P − O.',mom.r.map((v,i)=>n('r'+['x','y','z'][i]+' (m)',v)),'rOP = (2, 1, 0) m.'),choice('Set the cross-product order','Moments use a cross product, not a dot product. Reversing the order reverses its sign.','Which equation gives the requested moment?',['MO = rOP × F','MO = F × rOP','MO = rOP · F'],0,'Use r × F. The units are m × N = N·m.'),step('Calculate the moment vector','In the xy plane, Mz = rx Fy − ry Fx. The other components are zero.','Find MO.',mom.components.map((v,i)=>n('M'+['x','y','z'][i]+' (N·m)',v,.1)),'Mz = 2(100) − 1(50) = +150 N·m. MO = (0, 0, 150) N·m.'),step('Find the perpendicular arm','The moment arm is the perpendicular distance to the infinite force line, not the point-to-point distance |r|.','Find d = |M|/|F|.',[n('d (m)',mom.arm,.01)],'|F| = √(50² + 100²) = 111.803 N; d = 150/111.803 = 1.3416 m.'),choice('Interpret the sign','Use a right-handed coordinate system and view the xy plane from +z toward O.','What rotation does +Mz represent?',['Counterclockwise','Clockwise','No moment'],0,'The right-hand rule gives +z for counterclockwise rotation viewed from +z.')]},
 {id:'axis',title:'Moment about an axis',workspace:'axisWorkspace',description:'Normalize the axis, form the point moment, then extract the signed twist.',prompt:'Axis endpoints are <strong>A = (0, 0, 0) m</strong> and <strong>B = (3, 4, 0) m</strong>. Force <strong>F = (0, 0, 100) N</strong> acts at <strong>P = (2, 1, 0) m</strong>. Find the signed moment about <strong>A→B</strong>.',steps:[step('Read the axis endpoints','Choose the positive axis direction before calculating its unit vector. Both endpoints must use the same coordinate origin.','Enter A and B.',[...([0,0,0]).map((v,i)=>n('A'+['x','y','z'][i]+' (m)',v)),...([3,4,0]).map((v,i)=>n('B'+['x','y','z'][i]+' (m)',v))],'A = (0, 0, 0); B = (3, 4, 0) m. The positive direction is A→B.'),step('Normalize the axis','A direction vector must be normalized before projecting a moment.','Find uAB.',ax.unit.map((v,i)=>n('u'+['x','y','z'][i],v,.005)),'B − A = (3, 4, 0) m, with length 5 m. uAB = (0.6, 0.8, 0).'),step('Build r from a point on the axis','Use A as the moment reference because it lies on the specified axis. Ending r at P locates the force line.','Find rAP.',[n('rx (m)',2),n('ry (m)',1),n('rz (m)',0)],'rAP = P − A = (2, 1, 0) m.'),step('Calculate the point moment','The full moment is calculated before projecting it onto the axis.','Find MA = rAP × F.',ax.components.map((v,i)=>n('M'+['x','y','z'][i]+' (N·m)',v,.1)),'MA = (1·100, −2·100, 0) = (100, −200, 0) N·m.'),step('Project the moment','Only the component about the chosen positive axis is the requested twisting moment.','Find Maxis = uAB · MA.',[n('Signed axis moment (N·m)',ax.scalar,.1)],'Maxis = 0.6(100) + 0.8(−200) = −100 N·m.'),step('Separate sign from magnitude','The negative sign identifies rotation opposite the positive-axis right-hand rule. Magnitude must be nonnegative.','Find |Maxis|.',[n('Axis magnitude (N·m)',ax.magnitude,.1)],'|Maxis| = 100 N·m; retain −100 N·m when the question asks for the signed moment.')]},
 {id:'couples',title:'Couple moments',workspace:'coupleWorkspace',description:'Recognize equal opposite forces, choose separation, cross and check free-vector behavior.',prompt:'Force <strong>+F = (0, 100, 0) N</strong> acts at <strong>P = (2, 3, 0) m</strong>; <strong>−F</strong> acts at <strong>Q = (0, 0, 0) m</strong>. Find the couple moment and perpendicular line spacing.',steps:[choice('Identify a couple','Equal, opposite, parallel forces on different lines have zero resultant force but can produce a moment.','What is the net force?',['Zero','100 N in +y','200 N in +y'],0,'+F + (−F) = 0. Separated force lines still create a turning effect.'),step('Choose the separation order','For Mc = r × (+F), r points from the application point of −F to the application point of +F.','Find rQP = P − Q.',couple.separation.map((v,i)=>n('r'+['x','y','z'][i]+' (m)',v)),'rQP = (2, 3, 0) m. Choosing the opposite order would require crossing with −F.'),step('Compute the couple vector','Use one separation vector and one force. Do not double the force magnitude.','Find Mc = rQP × F.',couple.components.map((v,i)=>n('Mc'+['x','y','z'][i]+' (N·m)',v,.1)),'Mc = (0, 0, 2·100 − 3·0) = (0, 0, 200) N·m.'),step('Find the perpendicular spacing','The two vertical force lines are separated in x. The 3 m difference along y does not increase their perpendicular spacing.','Find d = |Mc|/|F|.',[n('Spacing d (m)',couple.arm,.01)],'d = 200/100 = 2 m, not the point-to-point distance √13 m.'),choice('Check reference independence','The force pair’s resultant is zero, so changing the reference point cancels its additional moment terms.','Does moving the reference point change Mc?',['No: a couple moment is a free vector','Yes: it always increases','Yes: it becomes zero at P'],0,'Individual force moments change, but their sum remains (0, 0, 200) N·m.')]}
 ];
 const hints={
 'Choose a component method':['Draw a right triangle with the force as its hypotenuse. Which axis is adjacent to the angle?','Use the force magnitude and the angle measured from +x; recall adjacent/hypotenuse = cos θ and opposite/hypotenuse = sin θ.'],
 'Resolve both forces':['Fx = F cos θ; Fy = F sin θ.','Use each force’s own magnitude and angle from the problem. Set your calculator to degrees and keep the quadrant signs.'],
 'Add matching components':['Rx = Ax + Bx; Ry = Ay + By.','Use all four signed components in your checked “Resolve both forces” row above. Add x to x and y to y.'],
 'Recover the magnitude':['R = √(Rx² + Ry²).','Use the resultant components from “Add matching components,” not the original force magnitudes.'],
 'Find and check the direction':['θ = atan2(Ry, Rx). On a TI-84, start with tan⁻¹(Ry/Rx) and correct the quadrant.','Use the signed Rx and Ry from your checked steps. Measure counterclockwise from +x; handle Rx = 0 separately.'],
 'Read the coordinates':['A = (Ax, Ay, Az); B = (Bx, By, Bz).','Read each point against the labelled axes from the common origin. The diagram is in the xy plane, so consider what that means for z.'],
 'Build the direction vector':['rAB = B − A, component by component.','Use your checked coordinates of A and B above. The direction is from the starting point A to the ending point B.'],
 'Normalize the direction':['|rAB| = √(rx² + ry² + rz²); uAB = rAB / |rAB|.','Use the displacement components from “Build the direction vector.” Divide every component by the same nonzero length; unit components are dimensionless.'],
 'Construct the cable force':['F = F uAB; multiply each unit component by the given force magnitude.','Use the cable magnitude in the problem and your checked uAB. The cable pulls from A toward B.'],
 'Check the result':['|F| = √(Fx² + Fy² + Fz²).','Use the force components you just constructed. Compare the magnitude with the given cable force as a consistency check.'],
 'Take the scalar projection':['Faxis = F · uAB = Fx ux + Fy uy + Fz uz.','Use the given Cartesian force and your checked axis unit vector. This is a signed scalar in newtons, not a three-component vector.'],
 'Recover the parallel vector':['Fparallel = Faxis uAB.','Use the signed scalar projection from the previous step and your checked axis unit vector. Multiply the scalar into each component.'],
 'Check the axis convention':['Reversing the positive axis replaces u with −u. Compare F · (−u) and [F · (−u)](−u).','Track the sign changes in the scalar and in the unit vector separately before considering their product.'],
 'Choose the moment reference':['For a moment about O, the position vector must start at O and end on the force’s line of action.','Use the reference point named in the question and the force application point P.'],
 'Build the position vector':['rOP = P − O, component by component.','Use the given reference and application-point coordinates in the same frame and length units.'],
 'Set the cross-product order':['Recall the moment definition and the right-hand rule. Swapping two vectors in a cross product reverses its sign.','Use the position vector from the reference to the force line, followed by the force vector. A dot product produces a scalar instead.'],
 'Calculate the moment vector':['Mx = ry Fz − rz Fy; My = rz Fx − rx Fz; Mz = rx Fy − ry Fx.','Use your checked rOP and the given force components. Keep component order and subtraction signs; the units are N·m.'],
 'Find the perpendicular arm':['d = |M| / |F|; |F| = √(Fx² + Fy² + Fz²).','Use your checked moment vector’s magnitude and the given nonzero force. d is the perpendicular distance to the force line, not |r|.'],
 'Interpret the sign':['Curl your right-hand fingers in the rotation direction; your thumb identifies the moment direction.','View the xy plane from +z toward the origin and compare the rotation with the sign of your checked Mz.'],
 'Read the axis endpoints':['Identify A and B in the prompt; the positive axis runs A→B.','Use endpoint coordinates in metres from the same origin. These locate the axis; they are not force components.'],
 'Normalize the axis':['rAB = B − A; uAB = rAB / √(rx² + ry² + rz²).','Use your checked axis endpoints. Normalize the endpoint difference, not the vector to the force application point.'],
 'Build r from a point on the axis':['rAP = P − A.','Use the force application point P and the checked point A on the axis. This r differs from the axis-direction vector rAB.'],
 'Calculate the point moment':['MA = rAP × F; components: (ry Fz − rz Fy, rz Fx − rx Fz, rx Fy − ry Fx).','Use your checked rAP and the given Cartesian force. Calculate all three moment components before projecting.'],
 'Project the moment':['Maxis = uAB · MA = ux Mx + uy My + uz Mz.','Use the checked axis unit vector and the checked point moment. Keep the sign relative to A→B.'],
 'Separate sign from magnitude':['Magnitude = |Maxis|.','Use your signed axis moment from “Project the moment.” Absolute value gives magnitude; the original sign still describes rotation.'],
 'Identify a couple':['Add the two force vectors to test the resultant; also check whether their lines of action coincide.','The given forces are equal, parallel and opposite. Distinguish the net force from the turning effect of separated lines.'],
 'Choose the separation order':['For Mc = rQP × (+F), use rQP = P − Q.','Locate where +F and −F act in the prompt. The separation starts at the negative-force point and ends at the positive-force point.'],
 'Compute the couple vector':['Mc = rQP × F; use the same cross-product component rules as a force moment.','Use your checked separation and the given +F. One separation and one force account for the entire couple.'],
 'Find the perpendicular spacing':['d = |Mc| / |F|.','Use the checked couple magnitude and one nonzero force magnitude. Spacing is perpendicular to the parallel force lines.'],
 'Check reference independence':['When changing reference, the added moment term depends on the resultant force of the pair.','Recall your net-force result from “Identify a couple.” Consider whether that resultant can add a moment when the reference moves.']
 };
 for(const p of problems)for(const s of p.steps){const [reminder,inputs]=hints[s.title];s.hint={reminder,inputs};}

 const work=(text,...equations)=>({text,equations});
 const normalization=[
  work('Start with the displacement from the previous step. AB means the direction from A to B; rAB contains both direction and length.','rAB = (3, 4, 0) m'),
  work('Find the full length using all three perpendicular components. This is the denominator used for every unit component.','|rAB| = √(3² + 4² + 0²) m = √25 m = 5 m'),
  work('Divide each displacement component by that same length. Metres cancel, so ux, uy and uz are dimensionless direction components.','ux = 3/5 = 0.6','uy = 4/5 = 0.8','uz = 0/5 = 0'),
  work('Assemble the unit vector. uAB points in exactly the same A→B direction as rAB, but has length one.','uAB = (ux, uy, uz) = (0.6, 0.8, 0)'),
  work('Check normalization before using this direction in a force or projection equation.','|uAB| = √(0.6² + 0.8² + 0²) = √1 = 1')
 ];
 const worked={
 'Read the coordinates':[work('Measure each point from O along the labelled x and y axes. Both points are in the xy plane, so their z coordinates are zero.','A = (1, 1, 0) m','B = (4, 5, 0) m'),work('These are point locations. Subtract them in the next step to obtain the displacement from A toward B.')],
 'Build the direction vector':[work('Use the coordinates you just found. Ending point minus starting point gives the requested A→B direction.','rAB = B − A'),work('Subtract matching coordinates, retaining their signs.','rx = 4 − 1 = 3 m','ry = 5 − 1 = 4 m','rz = 0 − 0 = 0 m'),work('Collect the components into one vector. This displacement still has length units.','rAB = (3, 4, 0) m')],
 'Normalize the direction':normalization,
 'Normalize the axis':[work('First form the positive axis displacement from your checked endpoints.','rAB = (3 − 0, 4 − 0, 0 − 0) m = (3, 4, 0) m'),...normalization.slice(1)],
 'Choose a component method':[work('The angle is measured from +x. In the right triangle, x is adjacent to θ and y is opposite θ.','cos θ = Fx/F','sin θ = Fy/F'),work('Multiply each relation by the force magnitude to isolate its component. Quadrant signs are supplied by sine and cosine.','Fx = F cos θ','Fy = F sin θ')],
 'Resolve both forces':[work('Use A’s magnitude and its own angle, in degree mode. A lies in quadrant I, so both components are positive.','Ax = 120 cos(30°) = 103.923 N','Ay = 120 sin(30°) = 60 N'),work('Repeat for B using 120°, not A’s angle. B lies in quadrant II: its x component is negative and its y component is positive.','Bx = 90 cos(120°) = −45 N','By = 90 sin(120°) = 77.942 N')],
 'Add matching components':[work('Take Ax and Bx from your checked component step. Add signed x components; the negative Bx subtracts from Ax.','Rx = Ax + Bx = 103.923 + (−45) = 58.923 N'),work('Add the y components separately. Both point toward +y.','Ry = Ay + By = 60 + 77.942 = 137.942 N'),work('The resulting vector combines those perpendicular components.','R = (58.923, 137.942) N')],
 'Recover the magnitude':[work('Use the resultant components from the previous step, which lie along perpendicular axes.','R = √(Rx² + Ry²)'),work('Substitute and evaluate. Keep unrounded component values in your calculator; displayed rounded values can give a slight difference.','R ≈ √(58.923² + 137.942²) N ≈ 150 N')],
 'Find and check the direction':[work('Determine the quadrant before interpreting inverse tangent: Rx and Ry are both positive, so the resultant is in quadrant I.'),work('Divide y by x and use inverse tangent in degree mode. Here no quadrant correction is required.','θ = tan⁻¹(137.942/58.923) ≈ 66.870°'),work('Measure the angle counterclockwise from +x. It lies between 30° and 120°, consistent with adding these two forces.')],
 'Construct the cable force':[work('Use the given magnitude and the unit direction obtained in the previous step. Multiplying by 100 N restores force units.','F = (100 N) uAB'),work('Multiply every component by the magnitude.','Fx = 100(0.6) = 60 N','Fy = 100(0.8) = 80 N','Fz = 100(0) = 0 N'),work('Collect the components; the cable pulls at A toward B.','F = (60, 80, 0) N')],
 'Check the result':[work('Use the constructed force components to recover the magnitude.','|F| = √(Fx² + Fy² + Fz²)'),work('Substitute, square, add and take the square root.','|F| = √(60² + 80² + 0²) N = √10000 N = 100 N'),work('This agrees with the given cable magnitude. The normalization preserved direction while letting the specified force set the size.')],
 'Take the scalar projection':[work('Use the given force and the checked dimensionless unit axis vector. The dot product measures the signed part of F along A→B.','Faxis = Fx ux + Fy uy + Fz uz'),work('Multiply matching components and add the three products.','Faxis = 100(0.6) + 50(0.8) + 0(0) = 60 + 40 + 0 = 100 N'),work('The positive sign means the projection points along the chosen positive A→B axis.')],
 'Recover the parallel vector':[work('Use the scalar projection from the previous step and the unit vector from normalization.','Fparallel = Faxis uAB'),work('Multiply the signed scalar into every unit component.','Fparallel,x = 100(0.6) = 60 N','Fparallel,y = 100(0.8) = 80 N','Fparallel,z = 100(0) = 0 N'),work('Collect the components. This vector lies on the axis, whereas Faxis alone is a signed number.','Fparallel = (60, 80, 0) N')],
 'Check the axis convention':[work('Reverse the axis by negating every unit component.','uBA = (−0.6, −0.8, 0)'),work('Recompute the signed dot product.','F · uBA = 100(−0.6) + 50(−0.8) = −100 N'),work('Multiply the new scalar by the new direction. Both signs reverse, so the parallel vector is unchanged.','Fparallel = (−100)(−0.6, −0.8, 0) = (60, 80, 0) N')],
 'Choose the moment reference':[work('The question asks for the moment about O. Therefore start r at O and end it at P on the force line.','rOP = P − O'),work('A moment measures the force’s turning effect about that reference; a different starting point generally changes the moment of a single force.')],
 'Build the position vector':[work('Subtract reference O from application point P, one coordinate at a time.','rx = 2 − 0 = 2 m','ry = 1 − 0 = 1 m','rz = 0 − 0 = 0 m'),work('Collect the components for the moment calculation.','rOP = (2, 1, 0) m')],
 'Set the cross-product order':[work('The moment definition uses the reference-to-force position vector first and force second.','MO = rOP × F'),work('Swapping the order reverses the result; a dot product would instead yield a scalar and cannot give the moment vector.','F − rOP = √(rOP × F)'),work('Length times force supplies the moment units N·m.')],
 'Calculate the moment vector':[work('Use rOP = (2, 1, 0) m from your checked step and the given F = (50, 100, 0) N. Expand r × F by components.'),work('Calculate x and y. Each term includes a zero z component.','Mx = ry Fz − rz Fy = 1(0) − 0(100) = 0 N·m','My = rz Fx − rx Fz = 0(50) − 2(0) = 0 N·m'),work('Calculate z with the signed subtraction, then collect the vector.','Mz = rx Fy − ry Fx = 2(100) − 1(50) = 150 N·m','MO = (0, 0, 150) N·m')],
 'Find the perpendicular arm':[work('Use the checked moment magnitude and find the given force magnitude.','|M| = √(0² + 0² + 150²) = 150 N·m','|F| = √(50² + 100² + 0²) = 111.803 N'),work('From |M| = |F| d, divide by the nonzero force magnitude. Units reduce to metres.','d = 150/111.803 ≈ 1.3416 m'),work('This is perpendicular distance to the infinite force line; the distance to P is not generally the moment arm.')],
 'Interpret the sign':[work('Your calculated Mz is positive, so the moment vector points along +z. View the xy plane from +z toward O.'),work('Point your right thumb along +z; your fingers curl counterclockwise. That is the rotation represented by +Mz.')],
 'Read the axis endpoints':[work('Read the two axis points from the prompt, retaining metre units and their common origin.','A = (0, 0, 0) m','B = (3, 4, 0) m'),work('The specified positive direction is A→B. These endpoints define the axis direction, not the force application point.')],
 'Build r from a point on the axis':[work('Choose A on the axis as the moment reference. The vector must end at force application point P, not at B.','rAP = P − A'),work('Subtract coordinate by coordinate and collect the displacement.','rx = 2 − 0 = 2 m','ry = 1 − 0 = 1 m','rz = 0 − 0 = 0 m','rAP = (2, 1, 0) m')],
 'Calculate the point moment':[work('Use checked rAP = (2, 1, 0) m and given F = (0, 0, 100) N. Expand rAP × F.'),work('Compute each signed component before projecting onto the axis.','Mx = 1(100) − 0(0) = 100 N·m','My = 0(0) − 2(100) = −200 N·m','Mz = 2(0) − 1(0) = 0 N·m'),work('Collect the full point moment. It is not yet the moment about A→B.','MA = (100, −200, 0) N·m')],
 'Project the moment':[work('Use the checked axis unit vector and point moment. A dot product extracts the signed moment component along A→B.','Maxis = ux Mx + uy My + uz Mz'),work('Substitute all three pairs of components.','Maxis = 0.6(100) + 0.8(−200) + 0(0) = 60 − 160 = −100 N·m'),work('The negative sign indicates twist opposite the right-hand-rule rotation about the positive axis.')],
 'Separate sign from magnitude':[work('Use the signed result from the preceding projection step. Absolute value removes only its sign.','|Maxis| = |−100| = 100 N·m'),work('Report 100 N·m for magnitude; report −100 N·m if the question requests the signed axis moment.')],
 'Identify a couple':[work('Write both given force vectors and add matching components.','Fnet = (0, 100, 0) + (0, −100, 0) = (0, 0, 0) N'),work('The net force is zero. The distinct parallel lines of action still create a turning effect: a couple moment.')],
 'Choose the separation order':[work('Pair the positive force with a separation pointing from the negative-force point Q to the positive-force point P.','rQP = P − Q'),work('Subtract the coordinates and collect the displacement.','rx = 2 − 0 = 2 m','ry = 3 − 0 = 3 m','rz = 0 − 0 = 0 m','rQP = (2, 3, 0) m')],
 'Compute the couple vector':[work('Use checked rQP = (2, 3, 0) m and +F = (0, 100, 0) N. One separation and one force represent the whole pair.','Mc = rQP × F'),work('Expand all components with the same cross-product order.','Mc,x = 3(0) − 0(100) = 0 N·m','Mc,y = 0(0) − 2(0) = 0 N·m','Mc,z = 2(100) − 3(0) = 200 N·m'),work('Collect the couple moment.','Mc = (0, 0, 200) N·m')],
 'Find the perpendicular spacing':[work('Take the checked couple magnitude and the magnitude of one force.','|Mc| = 200 N·m','|F| = 100 N'),work('Rearrange |Mc| = |F| d and divide.','d = 200/100 = 2 m'),work('Both force lines are vertical. The x separation is perpendicular to them; the 3 m separation along y does not increase the spacing.')],
 'Check reference independence':[work('About any reference O, add the two individual force moments.','Mc = rOP × F + rOQ × (−F)'),work('Factor the common force using cross-product distributivity.','Mc = (rOP − rOQ) × F = rQP × F'),work('The reference O cancels, leaving the same separation vector and force. A couple moment is therefore a free vector with unchanged value.','Mc = (0, 0, 200) N·m')]
 };
 for(const p of problems)for(const s of p.steps)s.worked=worked[s.title];

 function correct(step,answers){if(step.options)return answers.choice!==undefined&&Number(answers.choice)===step.answer;return step.fields.every((f,i)=>answers[i]!==undefined&&String(answers[i]).trim()!==''&&Number.isFinite(Number(answers[i]))&&(Math.abs(Number(answers[i])-f.value)<=f.tolerance+1e-12||step.precision===3&&Number(answers[i])===Number(f.value.toPrecision(3))));}
 const api={problems,correct};if(typeof module!=='undefined')module.exports=api;else root.RoadmapData=api;
})(typeof window!=='undefined'?window:globalThis);
